nps = []
for p in ps:
    np = []
    for c in p:
        nc =[c['rgb'][0] / 255, c['rgb'][1]/255, c['rgb'][2] / 255]
        np.append(f"vec3({nc[0]},{nc[1]},{nc[2]})")
    nps.append(np)


print("const pal = `vec3 get_color(float tr, float r) {")
print("\tvec3 c;")
template = "else if (r < %.2f) { c = %s ; }"
templater = "else if (tr < %.2f) {"
for i,p in enumerate(nps):
    total = len(nps)
    tr = 1/total * (i+1)
    if (i == 0):
        print("\t" + templater[5:] % tr)
    else:
        print("\t" + templater % tr)
    for j,c in enumerate(p):
        totalc = len(p)
        r = 1 / totalc * (j+1)
        if (j == 0):
            print("\t\t" + template[5:] % (r, c))
        else:
            print("\t\t" + template % (r, c))
    print("\t}")
print("\treturn c;")
print("}`")



